    let amount = 100;
    let ctoken = sui::coin::mint_for_testing<CToken<MainMarket, SUI>>(amount, ctx).into_balance();

    assert!(!obligation.deposit_types().contains(&type_name::with_defining_ids<SUI>()));

    // initial borrow
    obligation.deposit_ctoken<MainMarket, SUI>(ctoken);
    assert!(obligation.ctoken_amount_by_coin(type_name::with_defining_ids<SUI>()) == amount);

